  ${tReject ? "(inside the rejection region)" : "(outside the rejection region)"}.
&lt;/p&gt;
&lt;div class="bs-excel"&gt;&lt;span class="lbl"&gt;Excel&lt;/span&gt;
  &lt;span&gt;p-value ${tTwo ? `=T.DIST.2T(${Math.abs(tObs).toFixed(2)}, ${tDf})` : tRight ? `=T.DIST.RT(${tObs.toFixed(2)}, ${tDf})` : `=T.DIST(${tObs.toFixed(2)}, ${tDf}, TRUE)`}&lt;/span&gt;
  &lt;span&gt;critical ${tTwo ? `=T.INV.2T(${tAlpha.toFixed(2)}, ${tDf})` : tRight ? `=T.INV(${(1 - tAlpha).toFixed(2)}, ${tDf})` : `=T.INV(${tAlpha.toFixed(2)}, ${tDf})`}&lt;/span&gt;
